window.__APP_CHUNKS=window.__APP_CHUNKS||[];window.__APP_CHUNKS[3]="')\"><div class=\"pin\"><div class=\"pk\">БАЗА ПРОЕКТА</div><h2>Водоёмы и участки</h2><p>Не список «красивых мест», а карточки с личными фактами, гипотезами и тем, чего ещё не хватает.</p></div></div>\n    <div id=\"watersList\"></div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-methods\">\n    <div class=\"pagehero\" style=\"--pagebg:url('data:image/webp;base64,')\"><div class=\"pin\"><div class=\"pk\">ПРАКТИКА</div><h2>Методы ловли</h2><p>Сначала личные рабочие методы. Теория добавляется только если помогает принять решение на воде.</p></div></div>\n    <div id=\"methodsList\"></div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-gear\">\n    <div class=\"pagehero\" style=\"--pagebg:url('data:image/webp;base64,')\"><div class=\"pin\"><div class=\"pk\">АРСЕНАЛ</div><h2>Снасти и оборудование</h2><p>Подтверждённые модели отдельно от того, что ещё надо сверить по фотографии маркировки.</p></div></div>\n    <div class=\"card\"><div class=\"card-title\"><h3>МОЙ КОМПЛЕКТ</h3><div class=\"section-count\">8 записей</div></div><div id=\"gearList\"></div></div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-lures\">\n    <div class=\"pagehero\" style=\"--pagebg:url('data:image/webp;base64,')\"><div class=\"pin\"><div class=\"pk\">ПРИМАНКИ</div><h2>Рабочая библиотека</h2><p>Не переписываем весь ящик вручную: фиксируем доказанные приманки и постепенно каталогизируем фото.</p></div></div>\n    <div id=\"luresList\"></div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-knowledge\">\n    <div class=\"pagehero\" style=\"--pagebg:url('data:image/webp;base64,')\"><div class=\"pin\"><div class=\"pk\">МЕТОДОЛОГИЯ</div><h2>База знаний</h2><p>Как мы отличаем полезную рыболовную информацию от красивых, но пустых советов.</p></div></div>\n    <div class=\"card\"><div class=\"card-title\"><h3>ОСНОВНЫЕ ПРИНЦИПЫ</h3><div class=\"section-count\">4</div></div><div id=\"knowledgeList\"></div></div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-researchbase\">\n    <div class=\"pagehero\" style=\"--pagebg:url('data:image/webp;base64,')\"><div class=\"pin\"><div class=\"pk\">ИССЛЕДОВАНИЯ</div><h2>Гипотезы и проверка</h2><p>Здесь храним вопросы, которые реально могут объяснить успех и провал, а не общие «приметы рыбака».</p></div></div>\n    <div id=\"researchBaseList\"></div>\n    <div class=\"card\"><div class=\"card-title\"><h3>ИСТОЧНИКИ</h3><div class=\"section-count\">4</div></div><div id=\"researchSources\"></div></div>\n  </section>\n\n\n\n  \n  \n\n<section class=\"screen\" id=\"screen-fishgroup\">\n  <div class=\"fish25-group-page\">\n    <div class=\"fish25-group-head\">\n      <button class=\"fish25-round\" type=\"button\" onclick=\"go('fish',false)\">←</button>\n      <div class=\"fish25-group-title\">\n        <h2 id=\"fishGroupTitle\">Группа</h2>\n        <span id=\"fishGroupCount\"></span>\n      </div>\n      <button class=\"fish25-round\" type=\"button\" onclick=\"document.getElementById('fishGroupSearch').focus()\">⌕</button>\n    </div>\n\n    <div class=\"fish25-search\">\n      <span>⌕</span>\n      <input id=\"fishGroupSearch\" placeholder=\"Поиск в группе...\">\n      <button id=\"fishGroupClear\" type=\"button\">×</button>\n    </div>\n\n    <div class=\"fish25-grid\" id=\"fishGroupGrid\"></div>\n  </div>\n</section>\n<section class=\"screen\" id=\"screen-fishprofile\">\n  <div id=\"fishProfileContent\"></div>\n</section>\n<section class=\"screen\" id=\"screen-detail\">\n    <button class=\"detail-back\" id=\"detailBack\">← Назад</button>\n    <div id=\"detailContent\"></div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-search\">\n    <button class=\"detail-back\" onclick=\"go('home')\">← Главная</button>\n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>ПОИСК ПО ПРОЕКТУ</h3><div class=\"sub\" id=\"searchSummary\">Результаты</div></div>\n      </div>\n      <div id=\"globalSearchResults\"></div>\n    </div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-region\">\n    <div class=\"backrow\">\n      <button class=\"backbtn\" onclick=\"go('home')\">← Регионы</button>\n      <div class=\"region-mini\">карточка региона</div>\n    </div>\n    <div id=\"regionDetailHero\"></div>\n    <div id=\"regionDetailBody\"></div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-research\">\n\n    \n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>ГИДРОЛОГИЯ / ЭТАЛОН 2026</h3><div class=\"sub\">Нижневартовск · Обь</div></div>\n        <div class=\"kstatus\">A</div>\n      </div>\n      <div class=\"meta\">Официальные контрольные точки половодья 2026: 15.05 — 834 см; 08.07 — 924 см; 16.07 — 829 см; 23.07 — 616 см. Это историческая линия, не текущий уровень.</div>\n      <div class=\"warnbox\" style=\"margin-top:10px\">В live-режиме карточка должна использовать только свежую публикацию с датой источника. Если свежего значения нет, уровень не подставляется.</div>\n    </div>\n\n    <div class=\"card\" id=\"backendStatusCard\">\n      <div class=\"card-title\">\n        <div><h3>LIVE BACKEND</h3><div class=\"sub\" id=\"backendStatusText\">Проверяю доступность…</div></div>\n        <div class=\"kstatus\" id=\"backendStatusBadge\">—</div>\n      </div>\n      <div class=\"meta\">Если backend недоступен, приложение остаётся в режиме сохранённого примера и не выдаёт его за live-данные.</div>\n    </div>\n\n    <div class=\"trip-hero\" style=\"--tripbg:url('data:image/webp;base64,')\">\n      <div class=\"in\"><div class=\"k\">КУДА ЕХАТЬ СЕЙЧАС</div><h2>Живая разведка</h2><p>Реальные варианты ранжируются по свежим данным, доступу, правилам и твоему личному опыту.</p></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>ЖИВАЯ РАЗВЕДКА</h3><div class=\"sub\">Поиск не «лучших мест вообще», а реальных вариантов под текущий выезд.</div></div>\n      </div>\n\n      <div class=\"research-form\">\n        <div class=\"research-field research-wide\">\n          <label>ТОЧКА СТАРТА</label>\n          <input id=\"researchOrigin\" value=\"Нижневартовск\" placeholder=\"Город или точка старта\">\n        </div>\n        <div class=\"research-field\">\n          <label>МАКС. ДОРОГА</label>\n          <select id=\"researchTime\">\n            <option>2 часа</option><option selected>5 часов</option><option>8 часов</option><option>без ограничения</option>\n          </select>\n        </div>\n        <div class=\"research-field\">\n          <label>ТРАНСПОРТ</label>\n          <select id=\"researchTransport\">\n            <option selected>общественный + такси</option><option>автомобиль</option><option>поезд + такси</option><option>любой</option>\n          </select>\n        </div>\n        <div class=\"research-field\">\n          <label>ЦЕЛЬ</label>\n          <select id=\"researchFish\">\n            <option selected>хищник / динамика</option><option>щука</option><option>судак</option><option>жерех</option><option>фидер</option>\n          </select>\n        </div>\n        <div class=\"research-field\">\n          <label>ФОРМАТ</label>\n          <select id=\"researchMode\">\n            <option selected>берег</option><option>лодка</option><option>любой</option>\n          </select>\n        </div>\n        <div class=\"research-wide\"><button id=\"runResearch\" class=\"actionbtn\">ЗАПУСТИТЬ РАЗВЕДКУ</button></div>\n      </div>\n      <div id=\"researchStatus\" class=\"research-status\">Локальная версия показывает сохранённый пример по текущей рабочей ветке. Точки с подтверждёнными координатами уже можно сразу открыть в Яндекс Картах или Google Maps. Автопоиск новых точек подключается через backend.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>СОХРАНЁННЫЙ ПРИМЕР РАЗВЕДКИ</h3><div class=\"sub\">Алгоритм специально отбрасывает общие календарные прогнозы без локального подтверждения.</div></div>\n      </div>\n      <div id=\"rankResults\"></div>\n    </div>\n\n\n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>ПЕРСПЕКТИВНЫЕ ТОЧКИ</h3><div class=\"sub\">Не просто водоём: конкретная структура, координаты и быстрый маршрут.</div></div>\n      </div>\n      <div class=\"point-legend\">\n        Координата считается рабочей только если она подтверждена источником или личным полевым опытом.\n        Если точная точка не подтверждена, приложение не должно придумывать её.\n      </div>\n      <div id=\"precisionPoints\"></div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>ИСТОЧНИКИ И ИХ ВЕС</h3><div class=\"sub\">Что сейчас учитывается и что сознательно не считается сильным сигналом.</div></div>\n      </div>\n      <div id=\"sourceLedger\"></div>\n    </div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-trips\">\n    <div class=\"trip-hero\" style=\"--tripbg:url('data:image/webp;base64,')\">\n      <div class=\"in\"><div class=\"k\">КАНДИДАТЫ, НЕ БРОНИ</div><h2>Поездки из Щербинки</h2><p>Направления для короткого выезда. Перед решением они должны проходить живую проверку по воде, отчётам, доступу и правилам.</p></div>\n    </div>\n    <div id=\"tripsBlock\"></div>\n    <div class=\"card\">\n      <div class=\"card-title\"><h3>СТАТИСТИКА ПРОЕКТА</h3></div>\n      <div class=\"stats-grid\">\n        <div class=\"stat-card\"><div class=\"num\">4</div><div class=\"lab\">основных региона</div></div>\n        <div class=\"stat-card\"><div class=\"num\">2</div><div class=\"lab\">подтверждённые точки</div></div>\n        <div class=\"stat-card\"><div class=\"num\">63</div><div class=\"lab\">рыб в каталоге</div></div>\n        <div class=\"stat-card\"><div class=\"num\">5</div><div class=\"lab\">зафиксированных записей</div></div>\n      </div>\n      <div class=\"hint mt8\">Проект развивается: база знаний, карточки видов и навигация уже работают; карта уже работает на подтверждённых точках; полноценная live-разведка требует production-backend и актуальных провайдеров.</div>\n    </div>\n  </section>\n</div>\n\n<div class=\"bottomnav\">\n  <div class=\"navrow\">\n    <button class=\"navbtn active\" data-target=\"home\"><img loading=\"lazy\" src=\"data:image/webp;base64,\"><span>Главная</span></button>\n    <button class=\"navbtn\" data-target=\"map\"><img loading=\"lazy\" src=\"data:image/webp;base64,\"><span>Карта</span></button>\n    <button class=\"navbtn\" data-target=\"diary\"><img loading=\"lazy\" src=\"data:image/webp;base64,\"><span>Дневник</span></button>\n    <button class=\"navbtn\" data-target=\"fish\"><img loading=\"lazy\" src=\"data:image/webp;base64,\"><span>Рыбы</span></button>\n    <button class=\"navbtn\" data-target=\"research\"><img loading=\"lazy\" src=\"data:image/webp;base64,\"><span>Разведка</span></button>\n    <button class=\"navbtn\" data-target=\"knowledge\"><img loading=\"lazy\" src=\"data:image/svg+xml;base64,\"><span>База</span></button>\n    <button class=\"navbtn\" data-target=\"trips\"><img loading=\"lazy\" src=\"data:image/webp;base64,\"><span>Поездки</span></button>\n  </div>\n</div>\n\n<script src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\" crossorigin=\"\"></script>\n<script src=\"data/fish-knowledge.js?v=20260930-2\"></script>\n<script src=\"fish-card-v1.js?v=20260930-2\"></script>\n<script src=\"personal-store.js?v=20260930-2\"></script>\n<script>\nconst DATA = {\"assets\":{\"iconHome\":\"data:image/webp;base64,\",\"iconMap\":\"data:image/webp;base64,\",\"iconDiary\":\"data:image/webp;base64,\",\"iconFish\":\"data:image/webp;base64,\",\"iconTrips\":\"data:image/webp;base64,\",\"iconWhere\":\"data:image/webp;base64,\",\"iconWaters\":\"data:image/webp;base64,\",\"iconStats\":\"data:image/webp;base64,\",\"iconBrand\":\"data:image/webp;base64,\",\"heroNizh\":\"data:image/webp;base64,\",\"heroAstra\":\"data:image/webp;base64,";